// Ported verbatim from legacy client/src/data/charityData.ts. Real data —
// 98 real, named charities scored across 7 weighted dimensions, unifying
// GiveWell/Charity Navigator/CharityWatch/Candid ratings. Plain module,
// imported by both the Server Component pages and the client-side
// rankings/scorecard/evaluators explorer.

export type CloakStatus = "clear" | "mostly-clear" | "hazy" | "opaque";
export type Grade = "A+" | "A" | "A-" | "B+" | "B" | "B-" | "C+" | "C" | "C-" | "D" | "F";
export type GiveWellStatus = "top" | "standout" | "reviewed" | null;
export type CNRating = 4 | 3 | 2 | 1 | 0 | null;
export type CNGrade = "A+" | "A" | "A-" | "B+" | "B" | "B-" | "C+" | "C" | "D" | "F" | null;
export type CandidSeal = "platinum" | "gold" | "silver" | "bronze" | null;

export type Sector =
  | "Global Health"
  | "Cash Transfers"
  | "Humanitarian"
  | "Global Dev"
  | "Education"
  | "Environment"
  | "Animals"
  | "Children"
  | "Poverty"
  | "Agriculture"
  | "Water & Sanitation"
  | "Mental Health"
  | "Human Rights"
  | "Disaster Relief"
  | "Nutrition"
  | "Technology"
  | "Arts & Culture"
  | "Housing"
  | "Criminal Justice"
  | "Community Dev";

export interface ScoreBreakdown {
  impactOutcomes: number;
  transparency: number;
  dollarEfficiency: number;
  evidenceQuality: number;
  cloakScore: number;
  beneficiaryVoice: number;
  adaptability: number;
}

export interface Charity {
  slug: string;
  name: string;
  sector: Sector;
  totalScore: number;
  grade: Grade;
  scores: ScoreBreakdown;
  cloakStatus: CloakStatus;
  givewell: GiveWellStatus;
  cnStars: CNRating;
  charityWatch: CNGrade;
  candidSeal: CandidSeal;
  donationsM: number;
  founded: number;
  hq: string;
  website: string;
  tagline: string;
  impactMetric: string;
  beneficiaries: string;
}

export const SCORE_WEIGHTS = {
  impactOutcomes: 0.25,
  transparency: 0.2,
  dollarEfficiency: 0.15,
  evidenceQuality: 0.15,
  cloakScore: 0.1,
  beneficiaryVoice: 0.1,
  adaptability: 0.05,
} as const;

export const SCORE_DIMENSIONS: {
  key: keyof ScoreBreakdown;
  label: string;
  weight: number;
  description: string;
}[] = [
  { key: "impactOutcomes", label: "Verified Impact Outcomes", weight: 25, description: "Measurable, third-party-verified results per dollar. Uses DALY, QALY, SROI, cost-per-life-saved." },
  { key: "transparency", label: "Transparency & Disclosure", weight: 20, description: "Full financial disclosure, Candid Platinum Seal, open-data policies, Benford's Law compliance." },
  { key: "dollarEfficiency", label: "Dollar Efficiency", weight: 15, description: "Program expense ratio, fundraising efficiency, charitable commitment percentage." },
  { key: "evidenceQuality", label: "Evidence Quality & Rigor", weight: 15, description: "Randomized controlled trials, peer-reviewed studies, independent evaluations, replication quality." },
  { key: "cloakScore", label: "Cloak-vs-Clear Score", weight: 10, description: "Proprietary transparency metric: do they hide what matters? Benford's Law analysis on financials, disclosure completeness, accessibility of impact data." },
  { key: "beneficiaryVoice", label: "Beneficiary Voice & Feedback", weight: 10, description: "Does the charity listen to the people it serves? Feedback loops, community input, participatory design." },
  { key: "adaptability", label: "Adaptability & Learning", weight: 5, description: "Does the organization learn from failures? Pivot history, program iteration, honest reporting of setbacks." },
];

