function computeTotal(scores: ScoreBreakdown): number {
  return (
    Math.round(
      (scores.impactOutcomes * SCORE_WEIGHTS.impactOutcomes +
        scores.transparency * SCORE_WEIGHTS.transparency +
        scores.dollarEfficiency * SCORE_WEIGHTS.dollarEfficiency +
        scores.evidenceQuality * SCORE_WEIGHTS.evidenceQuality +
        scores.cloakScore * SCORE_WEIGHTS.cloakScore +
        scores.beneficiaryVoice * SCORE_WEIGHTS.beneficiaryVoice +
        scores.adaptability * SCORE_WEIGHTS.adaptability) *
        10,
    ) / 10
  );
}

function gradeFromScore(score: number): Grade {
  if (score >= 97) return "A+";
  if (score >= 93) return "A";
  if (score >= 90) return "A-";
  if (score >= 87) return "B+";
  if (score >= 83) return "B";
  if (score >= 80) return "B-";
  if (score >= 77) return "C+";
  if (score >= 73) return "C";
  if (score >= 70) return "C-";
  if (score >= 60) return "D";
  return "F";
}

function cloakFromScore(score: number): CloakStatus {
  if (score >= 90) return "clear";
  if (score >= 75) return "mostly-clear";
  if (score >= 55) return "hazy";
  return "opaque";
}

