export const CHARITIES: Charity[] = RAW_CHARITIES.map((c) => {
  const totalScore = computeTotal(c.scores);
  return {
    ...c,
    totalScore,
    grade: gradeFromScore(totalScore),
    cloakStatus: cloakFromScore(c.scores.cloakScore),
  };
}).sort((a, b) => b.totalScore - a.totalScore);

export const STATS = {
  avgScore: Math.round((CHARITIES.reduce((s, c) => s + c.totalScore, 0) / CHARITIES.length) * 10) / 10,
  aTierCount: CHARITIES.filter((c) => c.grade.startsWith("A")).length,
  opacityWarnings: CHARITIES.filter((c) => c.cloakStatus === "hazy" || c.cloakStatus === "opaque").length,
  givewellDirectedM: "$397M",
  totalCharities: CHARITIES.length,
};

export const ALL_SECTORS: Sector[] = Array.from(new Set(CHARITIES.map((c) => c.sector))).sort();
